INSERT INTO savory_social.note (id, user_id, title, content, merchant_id, topic_tags, location, like_count, comment_count, collect_count, view_count, audit_status, is_top, create_time, update_time) VALUES
(100,398,'鲜榨果汁打卡全攻略','作为一个资深吃货，今天终于来打卡鲜榨果汁。鲜榨果汁真的惊艳到我了！食材非常新鲜，分量也足，重点是价格很亲民。强烈推荐给所有喜欢火锅的朋友，绝对不会踩雷。建议错峰去，饭点人会比较多。',131,'["杭州吃喝","打卡","面食地图"]','杭州市上城区',381,5,87,2980,1,0,'2026-07-01 06:52:00',NOW()),
(101,162,'周末探店｜辣炒花蛤值不值得去','周末和朋友一起来辣炒花蛤，点了招牌辣炒花蛤和几道小菜。味道没得说，辣炒花蛤是全场最佳，火候掌握得恰到好处。环境也很干净，服务态度好。下次还会再来，已经安利给同事了。',130,'["美食探店","打卡","烧烤地图"]','杭州市滨江区',522,36,180,7192,1,1,'2026-08-07 13:56:00',NOW()),
